CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE meeting_status AS ENUM ('draft','discovering','awaiting_confirmation','calendar_pending','scheduled','calendar_failed','cancelled');
CREATE TYPE calendar_connection_kind AS ENUM ('organizer','availability');
CREATE TYPE connection_status AS ENUM ('active','revoked','expired');
CREATE TYPE job_status AS ENUM ('ready','leased','succeeded','failed','dead');

CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), discord_guild_id text NOT NULL UNIQUE, name text NOT NULL, time_zone text NOT NULL DEFAULT 'America/New_York', setup_status text NOT NULL DEFAULT 'started', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, discord_user_id text NOT NULL, member_id uuid, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id, discord_user_id));
CREATE TABLE members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, display_name text NOT NULL, calendar_invite_email text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id, calendar_invite_email));
CREATE TABLE capability_grants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, capability text NOT NULL, subject_kind text NOT NULL, subject_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id, capability, subject_kind, subject_id));
CREATE TABLE calendar_connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, member_id uuid REFERENCES members(id) ON DELETE CASCADE, kind calendar_connection_kind NOT NULL, provider text NOT NULL DEFAULT 'google_calendar', calendar_id text, account_email text NOT NULL, encrypted_refresh_token text NOT NULL, status connection_status NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK ((kind = 'organizer' AND member_id IS NULL AND calendar_id = 'primary') OR (kind = 'availability' AND member_id IS NOT NULL AND calendar_id IS NULL)));
CREATE UNIQUE INDEX calendar_connections_one_organizer_per_org ON calendar_connections(organization_id) WHERE kind = 'organizer';
CREATE UNIQUE INDEX calendar_connections_one_availability_per_member ON calendar_connections(member_id) WHERE kind = 'availability';
CREATE TABLE oauth_states (state text PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, member_id uuid REFERENCES members(id) ON DELETE CASCADE, kind calendar_connection_kind NOT NULL, code_verifier text NOT NULL, expires_at timestamptz NOT NULL, CHECK ((kind = 'organizer' AND member_id IS NULL) OR (kind = 'availability' AND member_id IS NOT NULL)));
CREATE TABLE meetings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, mode text NOT NULL, status meeting_status NOT NULL, title text NOT NULL, time_zone text NOT NULL, starts_at timestamptz, ends_at timestamptz, discovery_starts_at timestamptz, discovery_ends_at timestamptz, location text, notes text, created_by_user_id uuid NOT NULL REFERENCES users(id), discord_channel_id text NOT NULL, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE candidate_slots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid NOT NULL REFERENCES meetings(id) ON DELETE CASCADE, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, connected_participant_count integer NOT NULL, unconnected_participant_count integer NOT NULL, rank integer NOT NULL);
CREATE TABLE teams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL, kind text NOT NULL, discord_role_id text, created_by_user_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id, name));
CREATE TABLE team_members (team_id uuid NOT NULL REFERENCES teams(id) ON DELETE CASCADE, member_id uuid NOT NULL REFERENCES members(id) ON DELETE CASCADE, PRIMARY KEY(team_id, member_id));
CREATE TABLE meeting_participants (meeting_id uuid NOT NULL REFERENCES meetings(id) ON DELETE CASCADE, member_id uuid NOT NULL REFERENCES members(id), display_name_snapshot text NOT NULL, calendar_invite_email_snapshot text NOT NULL, attendance_role text NOT NULL DEFAULT 'required', PRIMARY KEY(meeting_id, member_id));
CREATE TABLE calendar_events (meeting_id uuid PRIMARY KEY REFERENCES meetings(id) ON DELETE CASCADE, calendar_connection_id uuid NOT NULL REFERENCES calendar_connections(id), external_event_id text NOT NULL, html_link text, status text NOT NULL DEFAULT 'synced', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, kind text NOT NULL, idempotency_key text NOT NULL UNIQUE, payload jsonb NOT NULL, status job_status NOT NULL DEFAULT 'ready', attempts integer NOT NULL DEFAULT 0, run_after timestamptz NOT NULL DEFAULT now(), lease_expires_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now());
